module reconstruct (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] B0,\n    input [7:0] B1,\n    input [7:0] B2,\n    input [7:0] B3,\n    output reg [15:0] A0,\n    output reg [15:0] A1,\n    output reg [15:0] A2,\n    output reg [15:0] A3,\n    output reg done\n);\n\n    wire [15:0] A0_temp = (B0 + B1 + B3 - (B2 << 1)) / 3;\n    wire [15:0] A1_temp = (B0 + B1 - B2) - (A0_temp << 1);\n    wire [15:0] A2_temp = B1 - A0_temp - A1_temp;\n    wire [15:0] A3_temp = B2 - A1_temp - A2_temp;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            A0 <= 16'd0;\n            A1 <= 16'd0;\n            A2 <= 16'd0;\n            A3 <= 16'd0;\n            done <= 1'b0;\n        end else begin\n            if (start) begin\n                A0 <= A0_temp;\n                A1 <= A1_temp;\n                A2 <= A2_temp;\n                A3 <= A3_temp;\n                done <= 1'b1;\n            end else begin\n                done <= 1'b0;\n            end\n        end\n    end\nendmodule